import{selectBars,padToSongStart,onlyBars}from'./range.js';
import{BarMap}from'./barmap.js';
import{loadKit}from'./kit.js';
import {zip} from './archive.js';
import * as alphaTab from './vendor/alphatab.js';
import{STYLES,analyze,demo,generate,midi,tempoMap,secondsAt,playbackOrder,clickEvents}from'./engine.js';
import{Player}from'./audio.js';
const $=id=>document.getElementById(id);
const option=(text,value,selected=false)=>{const el=document.createElement('option');el.textContent=text;el.value=value;el.selected=selected;return el};
const readBytes=file=>typeof file.arrayBuffer==='function'?file.arrayBuffer():new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error||Error('อ่านไฟล์จากอุปกรณ์ไม่สำเร็จ'));reader.readAsArrayBuffer(file)});
let fullSong=null,song=null,score=null,results=[],style='metalcore',playing=-1,revision=0,overrides=[];const player=new Player();
const barMap=new BarMap($('barMap'),(a,b)=>{$('barFrom').value=String(Math.min(a,b));$('barTo').value=String(Math.max(a,b));rangeChanged()});
const status=(text,error=false)=>{$('status').textContent=text;$('status').classList.toggle('error',error)};const seed=()=>crypto.getRandomValues(new Uint32Array(1))[0];
function stop(){player.stop();playing=-1;document.querySelectorAll('.song-card').forEach(c=>{c.classList.remove('playing');c.querySelector('.play-btn').textContent='▶';c.querySelector('.transport span').style.width='0%'});}
function reset(){stop();results=[];$('results').replaceChildren();$('resultCount').textContent='0';$('empty').hidden=false;$('downloadAll').hidden=true;$('resultNotes').hidden=true;revision++}
function setSong(next,keepOverrides=false){reset();fullSong=next;song=next;$('barRange').hidden=false;for(const id of ['barFrom','barTo']){$(id).max=String(next.bars.length)}$('barFrom').value='1';$('barTo').value=String(next.bars.length);$('rangeHint').textContent=`ทั้งเพลง · ${next.bars.length} ห้อง`;$('sourceInfo').hidden=false;$('songName').textContent=song.title;$('sourceStats').textContent=`${song.bpm} BPM / ${song.bars.length} bars / ${song.bars[0].numerator}:${song.bars[0].denominator}`;$('bpm').value=song.bpm;$('generate').disabled=false;$('scoreNote').textContent=next.expanded?`เล่นตาม repeat / ending: ${next.bars.length} ห้องตามลำดับที่เล่น (เขียนไว้ ${next.writtenBars} ห้อง) · เลขในวงเล็บคือห้องในโน้ต`:next.hasRepeats?'มี repeat / ending แต่กำลังอ่านตามลำดับห้องที่เขียน · เปิด Follow repeats & endings เพื่อเล่นตามจริง':'ใช้โน้ตกีตาร์และจังหวะจากแทร็กที่เลือก • อ่านตามลำดับห้องที่เขียน';$('repeatRow').hidden=!(next.expanded||next.hasRepeats);if(!keepOverrides||overrides.some(o=>o.to>next.bars.length))overrides=[];$('overrideBox').hidden=false;barMap.setSong(next);paintRange();renderOverrides();}
for(const [id,s]of Object.entries(STYLES)){const btn=document.createElement('button');btn.className='genre'+(id===style?' selected':'');btn.setAttribute('aria-pressed',String(id===style));const strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=s.name;small.textContent=s.sub;btn.append(strong,small);btn.onclick=()=>{style=id;document.querySelectorAll('.genre').forEach(b=>{b.classList.toggle('selected',b===btn);b.setAttribute('aria-pressed',String(b===btn))})};$('genres').append(btn)}
for(const id of ['density','complexity','follow','humanize'])$(id).oninput=()=>$(id+'Value').textContent=$(id).value+'%';
for(const [id,s]of Object.entries(STYLES))$('ovStyle').append(option(s.name,id,id==='thrash'));
for(const id of ['ovDensity','ovComplexity'])$(id).oninput=()=>$(id+'Value').textContent=$(id).value+'%';
function renderOverrides(){$('ovList').replaceChildren(...overrides.map((o,i)=>{const li=document.createElement('li'),text=document.createElement('span'),del=document.createElement('button');text.textContent=`Bar ${o.from}–${o.to} · ${STYLES[o.options.style].name} · ${o.options.density}% / ${o.options.complexity}%${o.options.doubleKick?' · double kick':''}`;del.type='button';del.textContent='×';del.setAttribute('aria-label',`ลบการตั้งค่า bar ${o.from}–${o.to}`);del.onclick=()=>{overrides.splice(i,1);renderOverrides();paintRange();if($('rangeMode').value==='overrides'){reset();updateRangeHint()}status('ลบการตั้งค่าเฉพาะช่วงแล้ว กด Generate เพื่อสร้างใหม่')};li.append(text,del);return li}))}
$('ovAdd').onclick=()=>{if(!fullSong)return;const n=fullSong.bars.length,from=Math.min(n,Math.max(1,Math.round(+$('barFrom').value)||1)),to=Math.min(n,Math.max(from,Math.round(+$('barTo').value)||from));overrides.push({from,to,options:{style:$('ovStyle').value,density:+$('ovDensity').value,complexity:+$('ovComplexity').value,follow:+$('follow').value,doubleKick:$('ovDouble').checked}});renderOverrides();paintRange();if($('rangeMode').value==='overrides'){reset();updateRangeHint()}status(`ตั้งแนว ${STYLES[$('ovStyle').value].name} ให้ bar ${from}–${to} แล้ว · `+($('rangeMode').value==='overrides'?'กด Generate ได้เลย':'เลือกช่วงที่จะสร้าง หรือเปลี่ยน Generate เป็นเฉพาะห้องที่ตั้งไว้ แล้วกด Generate'))};
$('exportAlign').onchange=()=>{if(!fullSong)return;paintRange();updateRangeHint()};
$('followRepeats').onchange=()=>{if(!score)return;try{setSong(analyzeScore(score,+$('track').value));status($('followRepeats').checked?'เล่นตาม repeat / ending แล้ว · เลขห้องเปลี่ยนตามลำดับที่เล่น':'อ่านตามลำดับห้องที่เขียนในโน้ต')}catch(e){status(e.message,true)}};
$('tempoMode').onchange=()=>{$('customTempoField').hidden=$('tempoMode').value!=='custom'};
$('demoBtn').onclick=()=>{score=null;$('repeatRow').hidden=true;setSong(demo());$('track').replaceChildren(option('Rhythm guitar — Demo','0'));$('uploadTitle').textContent='Demo riff loaded';$('uploadSub').textContent='คลิกเพื่อแทนที่ด้วยไฟล์ของคุณ';status('Demo พร้อมแล้ว เลือกแนวแล้วกด Generate grooves')};
function analyzeScore(parsed,trackIndex){let order=null;if($('followRepeats').checked){try{order=playbackOrder(parsed,alphaTab)}catch(e){status(e.message,true)}}return analyze(parsed,trackIndex,order)}
async function load(file){if(!file)return;if(!/\.(gp[345]?|gpx)$/i.test(file.name.trim())){status('กรุณาเลือกไฟล์ .gp, .gpx, .gp5, .gp4 หรือ .gp3',true);return}if(file.size>20*1024*1024){status('ไฟล์ใหญ่เกิน 20 MB กรุณาลดขนาดไฟล์',true);return}status('กำลังอ่านไฟล์ Guitar Pro…');$('generate').disabled=true;const rev=++revision;try{const bytes=new Uint8Array(await readBytes(file));if(rev!==revision)return;const parsed=alphaTab.importer.ScoreLoader.loadScoreFromBytes(bytes,new alphaTab.Settings());if(!parsed.masterBars.length||parsed.masterBars.length>512)throw Error('รองรับ 1–512 ห้องต่อไฟล์ กรุณาแบ่งเพลงยาวเป็นส่วนย่อย');const tracks=parsed.tracks.filter(t=>t.staves.some(s=>!s.isPercussion));if(!tracks.length)throw Error('ไม่พบแทร็กเครื่องดนตรีสำหรับใช้อ้างอิงริฟฟ์');const first=tracks.find(t=>/rhythm|guitar|กีตาร์/i.test(t.name))||tracks[0];const next=analyzeScore(parsed,first.index);score=parsed;setSong(next);$('track').replaceChildren(...tracks.map(t=>option(t.name||`Track ${t.index+1}`,String(t.index),t===first)));$('uploadTitle').textContent=file.name;$('uploadSub').textContent='อ่านไฟล์สำเร็จ · คลิกเพื่อเปลี่ยนไฟล์';status('อ่านไฟล์สำเร็จ เลือกแทร็กอ้างอิงและคาแรกเตอร์กลองได้เลย');}catch(err){status('อ่านไฟล์ไม่สำเร็จ: '+(err.message||'ไฟล์เสียหายหรือเวอร์ชันไม่รองรับ'),true);$('generate').disabled=!song}finally{$('file').value=''}}
$('file').onchange=e=>load(e.target.files[0]);const drop=$('dropzone');for(const name of ['dragenter','dragover'])drop.addEventListener(name,e=>{e.preventDefault();drop.classList.add('drag')});for(const name of ['dragleave','drop'])drop.addEventListener(name,e=>{e.preventDefault();drop.classList.remove('drag')});drop.addEventListener('drop',e=>load(e.dataTransfer.files[0]));$('track').onchange=()=>{if(score){try{setSong(analyzeScore(score,+$('track').value),true);status('อัปเดตริฟฟ์อ้างอิงแล้ว กด Generate เพื่อสร้างใหม่')}catch(e){status(e.message,true)}}};
function alignText(from){return from>1?($('exportAlign').value==='song'?`ไฟล์ส่งออกมีช่วงเงียบก่อน bar ${from} วางที่ 0:00 ใน DAW ได้เลย`:`ไฟล์ส่งออกเริ่มที่ 0 ให้วางที่ bar ${from} ในเพลงต้นฉบับ`):'ไฟล์ส่งออกเริ่มที่ต้นเพลง'}
function paintRange(){if(!fullSong)return;const n=fullSong.bars.length,a=Math.min(n,Math.max(1,Math.round(+$('barFrom').value)||1)),b=Math.min(n,Math.max(a,Math.round(+$('barTo').value)||a));barMap.paint(a,b,overrides);$('overrideTarget').textContent=`Bar ${a}–${b}`;$('ovAdd').textContent=`+ ใช้กับ bar ${a}–${b}`;$('alignNote').textContent='ส่งออกเฉพาะ bar ที่เลือก · '+alignText(song?.rangeStart||a)}
const overrideRanges=()=>{const list=overrides.map(o=>[o.from,o.to]).sort((a,b)=>a[0]-b[0]),out=[];for(const r of list){const last=out[out.length-1];if(last&&r[0]<=last[1]+1)last[1]=Math.max(last[1],r[1]);else out.push([...r])}return out};
const rangeText=ranges=>ranges.map(([a,b])=>a===b?`${a}`:`${a}–${b}`).join(', ');
function generateTarget(){if($('rangeMode').value!=='overrides')return{clip:selectBars(fullSong,$('barFrom').value,$('barTo').value),ranges:null};const ranges=overrideRanges();if(!ranges.length)throw Error('ยังไม่มี Section overrides · เลือกห้องแล้วกด + ใช้กับ bar … ก่อน หรือเปลี่ยน Generate เป็น From–To bars');return{clip:selectBars(fullSong,ranges[0][0],ranges[ranges.length-1][1]),ranges}}
function updateRangeHint(){if(!fullSong)return;try{const{clip,ranges}=generateTarget();$('rangeHint').textContent=ranges?`Generate เฉพาะ bar ${rangeText(ranges)} · ห้องระหว่างนั้นเงียบ · ${alignText(clip.rangeStart)}`:`Bar ${clip.rangeStart}–${clip.rangeEnd} · ${clip.bars.length} ห้อง · ${alignText(clip.rangeStart)}`;$('generate').disabled=false}catch(e){$('rangeHint').textContent=e.message;$('generate').disabled=true}}
$('rangeMode').onchange=()=>{if(!fullSong)return;reset();updateRangeHint();status($('rangeMode').value==='overrides'?'จะ generate เฉพาะห้องที่ตั้ง Section overrides ไว้':'จะ generate ตามช่วง From–To')};
function rangeChanged(){if(!fullSong)return;if($('rangeMode').value==='overrides'){paintRange();status('เลือกห้องแล้ว · กด + ใช้กับ bar … เพื่อเพิ่ม Section override');return}reset();paintRange();try{const clip=selectBars(fullSong,$('barFrom').value,$('barTo').value);$('rangeHint').textContent=`Bar ${clip.rangeStart}–${clip.rangeEnd} · ${clip.bars.length} ห้อง · ${alignText(clip.rangeStart)}`;$('generate').disabled=false;status('เลือกช่วงแล้ว กด Generate เพื่อสร้างเฉพาะห้องที่เลือก')}catch(e){$('rangeHint').textContent=e.message;$('generate').disabled=true;status(e.message,true)}}
for(const id of ['barFrom','barTo'])$(id).oninput=rangeChanged;
$('allBars').onclick=()=>{if(!fullSong)return;barMap.anchor=0;$('barFrom').value='1';$('barTo').value=String(fullSong.bars.length);rangeChanged()};
const readOptions=()=>({overrides:overrides.map(o=>({...o,options:{...o.options}})),style,density:+$('density').value,complexity:+$('complexity').value,follow:+$('follow').value,humanize:+$('humanize').value,fills:+$('fills').value,doubleKick:$('doubleKick').checked,bassEnabled:$('bassEnabled').checked,bassMode:$('bassMode').value});
$('generate').onclick=async()=>{if(!fullSong)return;let clip,ranges;try{({clip,ranges}=generateTarget())}catch(e){status(e.message,true);return;}const override=$('tempoMode').value==='custom'?+$('bpm').value:null;if(override!==null&&(!Number.isFinite(override)||override<30||override>350)){status('กรุณาระบุ BPM ระหว่าง 30–350',true);$('bpm').focus();return}reset();song=clip;$('generate').disabled=true;status(`กำลังสร้างกลองและเบสเฉพาะ bar ${ranges?rangeText(ranges):song.rangeStart+'–'+song.rangeEnd}…`);const rev=++revision;await new Promise(r=>setTimeout(r,50));if(rev!==revision)return;try{const opt=readOptions();results=Array.from({length:+$('count').value},(_,i)=>({...onlyBars(song,generate(song,opt,seed(),i%3),ranges),variant:i%3,override}));render();status(`สร้าง ${results.length} เวอร์ชันสำหรับ bar ${ranges?rangeText(ranges):song.rangeStart+'–'+song.rangeEnd} สำเร็จ · ฟังและส่งออกเฉพาะช่วงนี้ได้เลย`)}catch(e){status('สร้างไม่สำเร็จ: '+e.message,true)}finally{$('generate').disabled=false}};
const names=['The Backbone','Riff Machine','Controlled Chaos'];const descriptions=['Tight pocket · closed hats','Driving accents · ride cymbal','Open cymbals · double-kick energy'];
function render(){stop();$('empty').hidden=results.length>0;$('resultCount').textContent=String(results.length);$('downloadAll').hidden=!results.length;$('resultNotes').hidden=!results.length;$('results').replaceChildren();for(const[r,result]of results.entries()){const card=document.createElement('article');card.className='song-card';card.dataset.index=r;card.innerHTML=`<div class="card-top"><button class="play-btn" aria-label="Play variation ${r+1}">▶</button><div class="card-title"><strong>${String(r+1).padStart(2,'0')} / ${names[result.variant]}</strong><small></small></div><div class="export-buttons"><select class="export-part" aria-label="Export instrument"><option value="mix">Full mix</option><option value="drums">Drums</option><option value="bass">Bass</option><option value="click">Click</option><option value="mixclick">Full mix + click</option></select><button class="download">MIDI ↓</button><button class="download wav-download">WAV ↓</button></div></div><div class="grid-wrap"><div class="pattern" aria-label="First two measures drum pattern"></div></div><div class="card-bottom"><span class="details"></span><label><input type="checkbox" class="listen-drums" checked> Drums</label><label><input type="checkbox" class="listen-bass" checked> Bass</label><label><input type="checkbox" class="reference"> Reference guitar</label><label><input type="checkbox" class="listen-click"> Click</label><label><input type="checkbox" class="count-in"> Count-in</label><button class="regenerate">↻ New take</button></div><div class="transport"><span></span></div>`;if(!result.bassEvents?.length){card.querySelector('.listen-bass').checked=false;card.querySelector('.listen-bass').disabled=true;card.querySelector('.export-part option[value=bass]').disabled=true;}card.querySelector('.card-title small').textContent=STYLES[result.style].name+' · '+descriptions[result.variant];const duration=secondsAt(song.length,tempoMap(song,result.override));card.querySelector('.details').textContent=`Bar ${result.onlyBars?rangeText(result.onlyBars):(song.rangeStart??1)+'–'+(song.rangeEnd??song.bars.length)} · ${result.events.length} hits / ${result.bassEvents?.length||0} bass notes · ${Math.floor(duration/60)}:${String(Math.floor(duration%60)).padStart(2,'0')} · ${result.override||song.bpm} BPM${!result.override&&song.bars.some(b=>b.tempos.length)?' + tempo map':''}${result.options.overrides?.length?' · '+result.options.overrides.length+' section override'+(result.options.overrides.length>1?'s':''):''}`;
 const pattern=card.querySelector('.pattern'),window=Math.min(song.length,song.bars.slice(0,2).reduce((n,b)=>n+b.length,0));for(const[label,notes,cls]of [['CYM',[42,46,49,51],'hat'],['SNR',[38],'snare'],['KICK',[36],'kick'],['BASS',[],'bass']]){const lab=document.createElement('span');lab.className='row-label';lab.textContent=label;pattern.append(lab);for(let i=0;i<32;i++){const cell=document.createElement('span');cell.className='cell '+cls+(i%4===0?' beat':'')+((cls==='bass'?(result.bassEvents||[]).some(e=>Math.floor(e.beat/window*32)===i):result.events.some(e=>notes.includes(e.note)&&Math.floor(e.beat/window*32)===i))?' on':'');pattern.append(cell)}}
 card.querySelector('.play-btn').onclick=async()=>{if(playing===r){stop();return}stop();playing=r;card.classList.add('playing');card.querySelector('.play-btn').textContent='■';player.onProgress=p=>{card.querySelector('.transport span').style.width=p*100+'%'};player.onEnd=()=>stop();try{status('กำลังโหลดชุดเสียงกลอง…');await player.play(song,result,result.override,card.querySelector('.reference').checked,{drums:card.querySelector('.listen-drums').checked,bass:card.querySelector('.listen-bass').checked,click:card.querySelector('.listen-click').checked},{countIn:card.querySelector('.count-in').checked});if(playing===r)status('กำลังเล่นกลองและเบส SoundFont · เลือกแยกเครื่องดนตรีก่อนส่งออกได้')}catch(e){stop();status(e.message,true)}};for(const control of card.querySelectorAll('.reference,.listen-drums,.listen-bass,.listen-click,.count-in'))control.onchange=()=>{if(playing===r)stop()};card.querySelector('.wav-download').onclick=()=>exportWav(r,card.querySelector('.wav-download'),card.querySelector('.export-part').value);card.querySelector('.download').onclick=()=>{const p=payload(result);download(midi(p.song,p.result,result.override,card.querySelector('.export-part').value,$('midiTarget').value),filename(r,$('midiTarget').value).replace('.mid','_'+card.querySelector('.export-part').value+'.mid'),'audio/midi')};card.querySelector('.regenerate').onclick=()=>{results[r]={...onlyBars(song,generate(song,result.options,seed(),result.variant),result.onlyBars),variant:result.variant,override:result.override};render();status(`สร้าง take ใหม่สำหรับเวอร์ชัน ${r+1} แล้ว`)};$('results').append(card)}}
const payload=result=>{const r={...result,clickEvents:clickEvents(song)};return $('exportAlign').value==='song'&&song.rangeStart>1?padToSongStart(fullSong,song,r):{song,result:r}};
const filename=(i,target='gm')=>(song.title.replace(/[^\p{L}\p{N}_-]+/gu,'_').slice(0,70)||'riff')+(song.rangeStart?'_bars'+song.rangeStart+'-'+song.rangeEnd:'')+'_'+results[i].style+'_v'+(i+1)+(target==='ezbass'?'_EZbass':'')+'.mid';
function download(bytes,name,type){const url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
// Store-only ZIP so one download contains every variation, with no remote service.
$('downloadAll').onclick=async()=>{try{const blob=zip(results.map((r,i)=>({name:filename(i,$('midiTarget').value),data:(p=>midi(p.song,p.result,r.override,'mix',$('midiTarget').value))(payload(r))})));download(blob,'riff-forge-grooves.zip','application/zip')}catch(e){status('ดาวน์โหลดไม่สำเร็จ: '+e.message,true)}};
$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();$('help').onclick=e=>{if(e.target===$('help'))$('help').close()};window.addEventListener('pagehide',()=>stop());

let exporting=false;
async function exportWav(index,button,part){if(exporting){status('กำลังสร้าง WAV อีกไฟล์อยู่ กรุณารอสักครู่');return}const result=results[index],snapshot=payload(result),name=filename(index).replace(/\.mid$/,'_'+part+'.wav');let worker;exporting=true;stop();button.disabled=true;button.textContent='0%';try{status('กำลังโหลดเสียงและสร้าง WAV 44.1 kHz / 16-bit stereo…');const kit=await loadKit();worker=new Worker(new URL('./wav-worker.js',document.baseURI),{type:'module'});await new Promise((resolve,reject)=>{worker.onmessage=e=>{if(e.data.error){reject(Error(e.data.error));return}if(e.data.progress!==undefined)button.textContent=Math.round(e.data.progress*100)+'%';if(e.data.blob){download(e.data.blob,name,'audio/wav');resolve()}};worker.onerror=()=>reject(Error('สร้าง WAV ไม่สำเร็จ กรุณาลองอีกครั้ง'));worker.postMessage({song:snapshot.song,result:snapshot.result,override:result.override,kit,part})});status('ดาวน์โหลด WAV พร้อมเสียงแล้ว · '+alignText(song.rangeStart||1))}catch(e){status(e.message,true)}finally{worker?.terminate();exporting=false;button.disabled=false;button.textContent='WAV ↓'}}

